public StationResponse writeConfig(String stationKey, String requestId, String maxFlow,
                                   String maxRampPerMinute, Long expectedVersion, String actor) {
    requireKey("stationKey", stationKey); requireKey("requestId", requestId);
    BigDecimal flow = parseAmount("maxFlow", maxFlow);       // >0, ≤3 decimals
    BigDecimal ramp = parseAmount("maxRampPerMinute", maxRampPerMinute);
    if (expectedVersion == null || expectedVersion < 0) throw badRequest("INVALID_ARGUMENT", "expectedVersion 不能为空且必须大于等于 0");
    Map params = {maxFlow: flow.toPlainString(), maxRampPerMinute: ramp.toPlainString(), expectedVersion: expectedVersion}
    return runRequest("STATION_CONFIG", requestId, actor, stationKey, params, StationResponse.class, () -> {
        StationRow station = pumpRepository.lockByKey(stationKey);
        long now = nowNanos();
        if (station == null) {
            if (expectedVersion != 0) throw conflict("VERSION_CONFLICT", "泵站不存在，新建须使用 expectedVersion=0");
            long id = pumpRepository.insertStation(stationKey, flow, ramp, now);  // concurrent create → DuplicateKeyException
            return toStationResponse(pumpRepository.findByKey(stationKey));
        }
        if (expectedVersion != station.version()) throw conflict("VERSION_CONFLICT", "expectedVersion 与当前版本不一致");
        // 参数调小若使已有批准曲线非法则 409（判断前不舍入）
        List<List<Node>> approved = approvedCurves(stationKey, 0L);  // exclude none
        try {
