```java
package com.example.starter.water;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;

/**
 * 流量曲线数学工具：节点为 UTC 整分钟（epoch 分钟），流量单位立方米每分钟。
 * 相邻节点线性变化；叠加判定使用精确有理数运算，判断前不舍入。
 */
public final class FlowCurve {

    /** 曲线节点：minute 为 UTC epoch 分钟，flow 单位立方米每分钟（非负，最多 3 位小数）。 */
    public record Node(long minute, BigDecimal flow) {
    }

    private static final BigDecimal TWO = BigDecimal.valueOf(2);

    private FlowCurve() {
    }

    /** 梯形积分（单位立方米）：相邻节点线性变化下的精确水量。 */
    public static BigDecimal integrate(List<Node> nodes) {
        BigDecimal sum = BigDecimal.ZERO;
        for (int i = 0; i + 1 < nodes.size(); i++) {
            Node a = nodes.get(i);
            Node b = nodes.get(i + 1);
            BigDecimal minutes = BigDecimal.valueOf(b.minute() - a.minute());
            sum = sum.add(a.flow().add(b.flow()).multiply(minutes).divide(TWO));
        }
        return sum;
    }

    /**
     * 校验多条曲线叠加后在所有节点处流量不超过 maxFlow、所有区间斜率绝对值不超过 maxRamp。
     * 叠加在全部曲线节点的并集上逐点求值（每条曲线在其时间范围外贡献 0），
     * 求和采用精确有理数运算，判断前不舍入。
     */
    public static void assertWithinLimits(List<List<Node>> curves, BigDecimal maxFlow, BigDecimal maxRamp) {
        // 并集时刻
        TreeMap<Long, Boolean> times = new TreeMap<>();
        for (List<Node> curve : curves) {
            for (Node n : curve) times.put(n.minute(), Boolean.TRUE);
        }
        List<Long> union = new ArrayList<>(times.keySet());
        // 流量上限：逐点精确求和
        for (long t : union) {
            Rat sum = new Rat();
            for (List<Node> curve : curves) {
                addInterpolated(sum, curve, t);
            }
            if (sum.compareTo(maxFlow) > 0) {
                throw ApiException.quotaExceeded(...); // hmm — need distinct codes
            }
        }
        ...
    }
}
```

Wait — error codes: PUMP_FLOW_EXCEEDED vs PUMP_RAMP_EXCEEDED, both 422. ApiException needs a general 422 factory. I'll add `ApiException.unprocessable(String code, String message)`.

