        List<CurveNode> curve = pumpRepository.listCurveNodes(row.id()).stream()
                .map(n -> new CurveNode(WaterService.toIso(n.minuteUtc() * NANOS_PER_MINUTE),
                        WaterService.fmt(n.flow())))
