                WaterService.fmt(row.amount()), WaterService.fmt(row.heldAmount()), row.requester(),
                row.status(), WaterService.toIso(row.createdNanos()), WaterService.toIso(row.updatedNanos()),
                curve.isEmpty() ? null : curve, row.stationVersion());
