        for (String allocationKey : List.of(a, b)) {
            futures.add(pool.submit(() -> {
                ready.countDown();
                assertTrue(start.await(10, TimeUnit.SECONDS));
                return postJson("/api/allocations/" + allocationKey + "/approve",
                        Map.of("commandKey", key("ap")), null, 0)
